    "title": "Matthew 4: Wilderness Temptation & Call by the Sea",
    "subtitle": "After forty days fasting, Jesus defeats every wilderness temptation with Scripture, announces Heaven’s near Kingdom in Galilee, and calls fishermen Peter, Andrew, James, and John from their nets.",
    "summaryHook": "After forty days fasting, Jesus defeats every wilderness temptation with Scripture, announces Heaven’s near Kingdom in Galilee, and calls fishermen Peter, Andrew, James, and John from their nets.",
    "bigPictureText": "Establishes Jesus’ unshakeable loyalty to God’s word and gathers ordinary workers into lifelong discipleship.",
