    "title": "Matthew 16: Peter’s Confession at Caesarea Philippi & Taking Up the Cross",
    "subtitle": "By northern rock springs, Peter declares “You are the Christ, the Son of the living God!”—right before Jesus foretells His cross and teaches that losing life for Him saves it forever.",
    "summaryHook": "By northern rock springs, Peter declares “You are the Christ, the Son of the living God!”—right before Jesus foretells His cross and teaches that losing life for Him saves it forever.",
    "bigPictureText": "Unites glorious Messianic identity directly with self-giving cross-bearing loyalty.",
