    "title": "Matthew 17: Transfiguration Glory, Mustard-Seed Faith & Temple Coin",
    "subtitle": "Jesus’ face shines like the sun beside Moses and Elijah beneath the Father’s cloud (“Listen to him!”), heals an afflicted boy below the mountain, and pays the temple tax from a fish’s mouth.",
    "summaryHook": "Jesus’ face shines like the sun beside Moses and Elijah beneath the Father’s cloud (“Listen to him!”), heals an afflicted boy below the mountain, and pays the temple tax from a fish’s mouth.",
